        '    def align_camera(self, view):\n'
        '        """Change only the camera; axis views are orthographic, with Z up."""\n'
        "        if view == 'fit':\n"
        '            self.plotter.reset_camera(render=False)\n'
        '            self.plotter.render()\n'
        '            return\n'
        "        directions = {'origin': (1., 1., 1.), 'x+': (1., 0., 0.), 'x-': (-1., 0., 0.),\n"
        "                      'y+': (0., 1., 0.), 'y-': (0., -1., 0.),\n"
        "                      'z+': (0., 0., 1.), 'z-': (0., 0., -1.)}\n"
        "        if view not in directions: raise ValueError('지원하지 않는 카메라 방향입니다')\n"
        '        size = self.current_settings().size\n'
        '        fallback = np.array([0., size[0], 0., size[1], 0., size[2]])\n'
        '        try: bounds = np.asarray(self.plotter.bounds, dtype=float)\n'
        '        except (TypeError, ValueError): bounds = fallback\n'
        '        if (bounds.shape != (6,) or not np.isfinite(bounds).all()\n'
        '                or np.any(bounds[1::2] < bounds[::2])):\n'
        '            bounds = fallback\n'
        '        corners = np.array(list(product(*zip(bounds[::2], bounds[1::2]))))\n'
        '        centre = (bounds[::2] + bounds[1::2]) * .5\n'
        "        focal = np.zeros(3) if view == 'origin' else centre\n"
        '        outward = np.asarray(directions[view]); outward /= np.linalg.norm(outward)\n'
        "        up = np.array([0., 1., 0.]) if view.startswith('z') else np.array([0., 0., 1.])\n"
        '        right = np.cross(-outward, up); right /= np.linalg.norm(right)\n'
        '        screen_up = np.cross(right, -outward)\n'
        '        relative = corners - focal\n'
        '        widget = self.plotter.interactor\n'
        '        aspect = max(1, widget.width()) / max(1, widget.height())\n'
        '        scale = max(1e-3, 1.08 * max(float(np.abs(relative @ screen_up).max()),\n'
        '                                    float(np.abs(relative @ right).max()) / aspect))\n'
        '        diagonal = max(1., float(np.linalg.norm(bounds[1::2] - bounds[::2])))\n'
        '        offset = float(np.linalg.norm(centre - focal))\n'
        '        distance = 3. * diagonal + offset\n'
        '        camera = self.plotter.camera\n'
        '        camera.position = tuple(focal + outward * distance)\n'
        '        camera.focal_point = tuple(focal)\n'
        '        camera.up = tuple(up)\n'
        '        camera.parallel_projection = True\n'
        '        camera.parallel_scale = scale\n'
        '        camera.clipping_range = (max(1e-3, distance - diagonal - offset), distance + diagonal + offset)\n'
        '        self.plotter.render()\n'
