        "                                   if url.isLocalFile() and url.host().lower() in ('', 'localhost'))\n"
        '\n'
        '    def eventFilter(self, watched, event):\n'
        '        if event.type() in (QtCore.QEvent.DragEnter, QtCore.QEvent.DragMove, QtCore.QEvent.Drop):\n'
        '            paths = self.paths_from_mime(event.mimeData())\n'
        '            if not self.import_unavailable() and paths and event.possibleActions() & QtCore.Qt.CopyAction:\n'
        '                event.setDropAction(QtCore.Qt.CopyAction)\n'
        '                event.accept()\n'
        '                if event.type() == QtCore.QEvent.Drop:\n'
        '                    self.import_paths(paths, ignored=len(event.mimeData().urls()) - len(paths))\n'
        '            else:\n'
        '                event.ignore()\n'
        '            return True\n'
        '        return super().eventFilter(watched, event)\n'
        '\n'
        '    def import_paths(self, paths, ignored=0):\n'
        '        if self.import_unavailable():\n'
